const input = $input.first()?.json || {};
const body = input.body || input;

const email = (body.email || 'delivered@resend.dev').trim().toLowerCase();
const name = body.name || email.split('@')[0] || 'Reader';
const city = body.city || 'Lagos';
const countryCode = body.country_code || 'NG';

const newsCategories = Array.isArray(body.news_categories)
  ? body.news_categories
  : (Array.isArray(body.categories) ? body.categories : ['technology', 'economy', 'science']);

const weatherCategories = Array.isArray(body.weather_categories)
  ? body.weather_categories
  : ['current-temperature', 'weather-condition', 'high-low', 'rain-chance'];

let sendTime = body.send_time || '07:00:00';
if (/^\d{1,2}:\d{2}$/.test(sendTime)) {
  sendTime = sendTime.padStart(5, '0') + ':00';
} else if (!/^\d{2}:\d{2}:\d{2}$/.test(sendTime)) {
  const hr = typeof body.delivery_hour === 'number' ? body.delivery_hour : 7;
  sendTime = String(hr).padStart(2, '0') + ':00:00';
}

const token = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
  const r = Math.random() * 16 | 0;
  const v = c === 'x' ? r : (r & 0x3 | 0x8);
  return v.toString(16);
});

const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
let appUrl = (body.frontend_url || body.app_url || 'https://betadigest.online').trim().replace(/\/+$/, '');
if (!appUrl || appUrl.includes('localhost') || appUrl.includes('127.0.0.1')) {
  appUrl = 'https://betadigest.online';
}
const verificationUrl = `${appUrl}/verify?token=${token}`;

return [{
  json: {
    email,
    name,
    city,
    country_code: countryCode,
    news_categories: newsCategories,
    weather_categories: weatherCategories,
    send_time: sendTime,
    last_sent_date: body.last_sent_date || null,
    token,
    expires_at: expiresAt,
    verification_url: verificationUrl
  }
}];

